// src/components/trading/Trading.js
import React, { useState } from 'react';
import { useTheme } from '../../contexts/ThemeContext';
import { tradeAPI, marketAPI } from '../../services/api';

export default function Trading() {
  const [orderType, setOrderType] = useState('buy');
  const [selectedAsset, setSelectedAsset] = useState('SBER');
  const [quantity, setQuantity] = useState('');
  const [price, setPrice] = useState('');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const { isDark } = useTheme();

  const assets = [
    { symbol: 'SBER', name: 'Сбербанк', figi: 'BBG004730N88', currentPrice: 275.50 },
    { symbol: 'GAZP', name: 'Газпром', figi: 'BBG004730RP0', currentPrice: 172.30 },
    { symbol: 'LKOH', name: 'Лукойл', figi: 'BBG00475JZZ6', currentPrice: 5890.25 },
    { symbol: 'YNDX', name: 'Яндекс', figi: 'BBG006L8G4H1', currentPrice: 4650.75 }
  ];

  const handleSubmitOrder = async (e) => {
    e.preventDefault();
    
    if (!quantity || !price) {
      setMessage('Пожалуйста, заполните количество и цену');
      return;
    }

    setLoading(true);
    setMessage('');

    try {
      const selectedAssetData = assets.find(asset => asset.symbol === selectedAsset);
      
      // Пробуем разные форматы данных
      const orderData = {
        // Вариант 1: Основные поля
        figi: selectedAssetData.figi,
        operation: orderType.toUpperCase(), // 'BUY' или 'SELL'
        quantity: parseInt(quantity),
        price: parseFloat(price),
        
        // Вариант 2: Альтернативные названия полей
        // instrument: selectedAssetData.figi,
        // direction: orderType,
        // lots: parseInt(quantity),
        // order_price: parseFloat(price),
        
        // Дополнительные поля которые могут требоваться
        instrument_type: 'share', // или 'stock', 'share'
        order_type: 'limit', // или 'market'
        account_id: 'default' // если требуется указать счет
      };

      console.log('Отправка ордера:', orderData);
      
      const response = await tradeAPI.executeOrder(orderData);
      
      setMessage(`✅ Ордер успешно исполнен! ${orderType === 'buy' ? 'Покупка' : 'Продажа'} ${quantity} акций ${selectedAsset} по цене ${price} ₽`);
      
      // Очищаем форму после успешной отправки
      setQuantity('');
      setPrice('');
      
    } catch (error) {
      console.error('Ошибка исполнения ордера:', error);
      console.error('Детали ошибки:', error.response?.data);
      
      // Более детальное отображение ошибки
      const errorData = error.response?.data;
      if (errorData) {
        if (errorData.detail) {
          setMessage(`❌ Ошибка: ${errorData.detail}`);
        } else if (typeof errorData === 'object') {
          // Показываем все поля ошибки
          const errorMessages = Object.entries(errorData)
            .map(([key, value]) => `${key}: ${Array.isArray(value) ? value.join(', ') : value}`)
            .join('; ');
          setMessage(`❌ Ошибка валидации: ${errorMessages}`);
        } else {
          setMessage(`❌ Ошибка: ${JSON.stringify(errorData)}`);
        }
      } else {
        setMessage(`❌ Ошибка: ${error.message || 'Неизвестная ошибка'}`);
      }
    } finally {
      setLoading(false);
    }
  };

  // Функция для тестирования разных форматов данных
  const testOrderFormat = async () => {
    const selectedAssetData = assets.find(asset => asset.symbol === selectedAsset);
    
    const testFormats = [
      {
        name: "Формат 1 (основной)",
        data: {
          figi: selectedAssetData.figi,
          operation: orderType.toUpperCase(),
          quantity: parseInt(quantity),
          price: parseFloat(price),
        }
      },
      {
        name: "Формат 2 (альтернативный)",
        data: {
          instrument: selectedAssetData.figi,
          direction: orderType,
          lots: parseInt(quantity),
          order_price: parseFloat(price),
        }
      },
      {
        name: "Формат 3 (расширенный)",
        data: {
          figi: selectedAssetData.figi,
          operation: orderType.toUpperCase(),
          quantity: parseInt(quantity),
          price: parseFloat(price),
          instrument_type: 'share',
          order_type: 'limit'
        }
      }
    ];

    for (const format of testFormats) {
      console.log(`Тестируем ${format.name}:`, format.data);
      try {
        const response = await tradeAPI.executeOrder(format.data);
        console.log(`✅ ${format.name} успешен:`, response.data);
        setMessage(`✅ Успех с ${format.name}!`);
        return;
      } catch (error) {
        console.log(`❌ ${format.name} failed:`, error.response?.data);
      }
    }
    
    setMessage('❌ Все форматы не прошли валидацию');
  };

  // Функция для загрузки текущей рыночной цены
  const loadCurrentPrice = async (symbol) => {
    try {
      const asset = assets.find(a => a.symbol === symbol);
      if (!asset) return;
      
      const response = await marketAPI.loadCandles(asset.figi, 1);
      
      if (response.data && response.data.candles && response.data.candles.length > 0) {
        const latestCandle = response.data.candles[0];
        return latestCandle.c; // цена закрытия последней свечи
      }
    } catch (error) {
      console.error('Ошибка загрузки текущей цены:', error);
    }
    return null;
  };

  // Функция для установки рыночной цены
  const handleSetMarketPrice = async () => {
    const marketPrice = await loadCurrentPrice(selectedAsset);
    if (marketPrice) {
      setPrice(marketPrice.toString());
      setMessage(`✅ Текущая рыночная цена: ${marketPrice} ₽`);
    } else {
      setMessage('❌ Не удалось загрузить текущую цену');
    }
  };

  const selectedAssetData = assets.find(asset => asset.symbol === selectedAsset);

  return (
    <div className="space-y-6">
      <div className={`rounded-3xl p-8 text-white shadow-2xl ${
        isDark
          ? 'bg-gradient-to-r from-green-600 to-cyan-600'
          : 'bg-gradient-to-r from-blue-500 to-purple-600'
      }`}>
        <h1 className="text-3xl font-bold mb-2">Торговля</h1>
        <p className={isDark ? 'text-cyan-100' : 'text-blue-100'}>
          Совершайте сделки с AI-рекомендациями
        </p>
      </div>

      {/* Сообщения */}
      {message && (
        <div className={`p-4 rounded-2xl ${
          message.includes('❌') 
            ? 'bg-red-100 border border-red-300 text-red-700 dark:bg-red-900 dark:border-red-700 dark:text-red-200'
            : 'bg-green-100 border border-green-300 text-green-700 dark:bg-green-900 dark:border-green-700 dark:text-green-200'
        }`}>
          {message}
        </div>
      )}

      {/* Кнопка для тестирования форматов (временно) */}
      <div className="bg-yellow-100 border border-yellow-300 text-yellow-700 p-4 rounded-2xl">
        <p className="text-sm mb-2">Для отладки: проверьте консоль браузера для деталей ошибки 422</p>
        <button
          onClick={testOrderFormat}
          className="px-4 py-2 bg-yellow-500 text-white rounded-lg text-sm font-medium"
        >
          Тест форматов данных
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Панель торговли */}
        <div className="lg:col-span-1">
          <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
            <h3 className="text-xl font-semibold text-gray-800 dark:text-white mb-4">
              Новая сделка
            </h3>
            
            <form onSubmit={handleSubmitOrder} className="space-y-4">
              {/* Переключатель покупки/продажи */}
              <div className="flex rounded-2xl bg-gray-100 dark:bg-gray-700 p-1">
                <button
                  type="button"
                  onClick={() => setOrderType('buy')}
                  className={`flex-1 py-3 px-4 rounded-2xl text-sm font-semibold transition-all duration-300 ${
                    orderType === 'buy'
                      ? 'bg-green-500 text-white shadow-lg'
                      : 'text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-white'
                  }`}
                >
                  Покупка
                </button>
                <button
                  type="button"
                  onClick={() => setOrderType('sell')}
                  className={`flex-1 py-3 px-4 rounded-2xl text-sm font-semibold transition-all duration-300 ${
                    orderType === 'sell'
                      ? 'bg-red-500 text-white shadow-lg'
                      : 'text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-white'
                  }`}
                >
                  Продажа
                </button>
              </div>

              {/* Выбор актива */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Актив
                </label>
                <select
                  value={selectedAsset}
                  onChange={(e) => setSelectedAsset(e.target.value)}
                  className={`w-full rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:border-transparent transition-all duration-300 ${
                    isDark
                      ? 'bg-gray-700 border-gray-600 text-white focus:ring-cyan-500'
                      : 'border border-gray-300 focus:ring-blue-500'
                  }`}
                >
                  {assets.map((asset) => (
                    <option key={asset.symbol} value={asset.symbol}>
                      {asset.name} ({asset.symbol})
                    </option>
                  ))}
                </select>
              </div>

              {/* Текущая цена */}
              {selectedAssetData && (
                <div className={`p-4 rounded-2xl ${
                  isDark ? 'bg-gray-700' : 'bg-gray-100'
                }`}>
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-600 dark:text-gray-400">Текущая цена:</span>
                    <span className="text-lg font-bold text-gray-800 dark:text-white">
                      {selectedAssetData.currentPrice.toLocaleString('ru-RU')} ₽
                    </span>
                  </div>
                  <button
                    type="button"
                    onClick={handleSetMarketPrice}
                    className="w-full mt-2 py-2 px-4 bg-blue-500 hover:bg-blue-600 text-white rounded-xl text-sm font-medium transition-colors"
                  >
                    Установить рыночную цену
                  </button>
                </div>
              )}

              {/* Количество */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Количество
                </label>
                <input
                  type="number"
                  value={quantity}
                  onChange={(e) => setQuantity(e.target.value)}
                  placeholder="0"
                  min="1"
                  className={`w-full rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:border-transparent transition-all duration-300 ${
                    isDark
                      ? 'bg-gray-700 border-gray-600 text-white focus:ring-cyan-500'
                      : 'border border-gray-300 focus:ring-blue-500'
                  }`}
                  disabled={loading}
                />
              </div>

              {/* Цена */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Цена (₽)
                </label>
                <input
                  type="number"
                  value={price}
                  onChange={(e) => setPrice(e.target.value)}
                  placeholder="0.00"
                  step="0.01"
                  min="0"
                  className={`w-full rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:border-transparent transition-all duration-300 ${
                    isDark
                      ? 'bg-gray-700 border-gray-600 text-white focus:ring-cyan-500'
                      : 'border border-gray-300 focus:ring-blue-500'
                  }`}
                  disabled={loading}
                />
              </div>

              {/* Сумма */}
              {quantity && price && (
                <div className={`p-4 rounded-2xl ${
                  isDark ? 'bg-gray-700' : 'bg-gray-100'
                }`}>
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-600 dark:text-gray-400">Общая сумма:</span>
                    <span className="text-lg font-bold text-gray-800 dark:text-white">
                      {(quantity * price).toLocaleString('ru-RU', {minimumFractionDigits: 2})} ₽
                    </span>
                  </div>
                </div>
              )}

              {/* Кнопка отправки */}
              <button
                type="submit"
                disabled={loading || !quantity || !price}
                className={`w-full py-3 rounded-2xl font-semibold text-white shadow-lg hover:shadow-xl transform hover:-translate-y-0.5 transition-all duration-300 disabled:opacity-50 disabled:transform-none disabled:hover:shadow-lg ${
                  orderType === 'buy'
                    ? 'bg-gradient-to-r from-green-600 to-cyan-600 hover:from-green-700 hover:to-cyan-700'
                    : 'bg-gradient-to-r from-red-600 to-pink-600 hover:from-red-700 hover:to-pink-700'
                }`}
              >
                {loading ? (
                  <div className="flex items-center justify-center">
                    <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white mr-2"></div>
                    Исполнение...
                  </div>
                ) : (
                  `${orderType === 'buy' ? 'Купить' : 'Продать'} ${selectedAsset}`
                )}
              </button>
            </form>
          </div>
        </div>

        {/* AI рекомендации и информация */}
        <div className="lg:col-span-2 space-y-6">
          {/* AI рекомендация */}
          <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
            <h3 className="text-xl font-semibold text-gray-800 dark:text-white mb-4">
              AI Рекомендация для {selectedAssetData?.name}
            </h3>
            <div className={`p-6 rounded-2xl ${
              isDark ? 'bg-green-500/20 border border-green-500/30' : 'bg-green-50 border border-green-200'
            }`}>
              <div className="flex items-center space-x-4">
                <div className={`p-3 rounded-2xl ${
                  isDark ? 'bg-green-500/30' : 'bg-green-100'
                }`}>
                  <svg className="w-8 h-8 text-green-600 dark:text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />
                  </svg>
                </div>
                <div>
                  <h4 className="text-lg font-bold text-gray-800 dark:text-white">Сильная покупка</h4>
                  <p className="text-gray-600 dark:text-gray-400 mt-1">
                    Модель предсказывает рост на 15% в ближайшие 30 дней с точностью 87%
                  </p>
                  <div className="flex items-center mt-3 space-x-4">
                    <div className="flex items-center">
                      <div className="w-24 bg-gray-200 dark:bg-gray-700 rounded-full h-2 mr-3">
                        <div className="bg-green-500 h-2 rounded-full" style={{width: '87%'}}></div>
                      </div>
                      <span className="text-sm text-gray-600 dark:text-gray-400">87% точность</span>
                    </div>
                    <div className="flex items-center">
                      <div className="w-24 bg-gray-200 dark:bg-gray-700 rounded-full h-2 mr-3">
                        <div className="bg-blue-500 h-2 rounded-full" style={{width: '92%'}}></div>
                      </div>
                      <span className="text-sm text-gray-600 dark:text-gray-400">92% уверенность</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* График и дополнительная информация */}
          <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
            <h3 className="text-xl font-semibold text-gray-800 dark:text-white mb-4">
              Технический анализ
            </h3>
            <div className={`h-64 rounded-2xl flex items-center justify-center ${
              isDark ? 'bg-gray-700' : 'bg-gray-100'
            }`}>
              <span className={isDark ? 'text-gray-400' : 'text-gray-500'}>
                График цены и технические индикаторы появятся здесь
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
